import fs from 'node:fs';
import { isWrapped, resolveBinPath, BACKUP_SUFFIX } from './utils.js';

const WRAPPER_TEMPLATE = `#!/bin/sh
# Auto-generated by @lionad/bin-timeout-wrapper
# Wraps: {bin_path}_backup
# Timeout: {timeout}s (override with BIN_TIMEOUT env var)

TIMEOUT="\${BIN_TIMEOUT:-{timeout}}"
exec perl -e '
  use strict;
  use warnings;
  my $timeout = $ARGV[0];
  my @cmd = @ARGV[1..$#ARGV];
  defined(my $pid = fork()) or die "fork: $!\\n";
  if ($pid == 0) {
    exec @cmd;
    die "exec: $!\\n";
  }
  $SIG{ALRM} = sub { kill 9, $pid };
  alarm $timeout;
  waitpid($pid, 0);
  exit($? >> 8 == 0 ? ($? & 127) ? 128 + ($? & 127) : 0 : $? >> 8);
' "$TIMEOUT" "{bin_path}_backup" "$@"
`;

export async function wrap(binPath, timeout) {
  const resolvedPath = resolveBinPath(binPath);

  if (isWrapped(resolvedPath)) {
    throw new Error(`Already wrapped: ${resolvedPath}`);
  }

  const backupPath = resolvedPath + BACKUP_SUFFIX;

  if (fs.existsSync(backupPath)) {
    throw new Error(`Backup already exists: ${backupPath}. Remove it or restore first.`);
  }

  fs.renameSync(resolvedPath, backupPath);

  const wrapperContent = WRAPPER_TEMPLATE
    .replaceAll('{bin_path}', resolvedPath)
    .replaceAll('{timeout}', String(timeout));

  fs.writeFileSync(resolvedPath, wrapperContent, 'utf-8');
  fs.chmodSync(resolvedPath, 0o755);

  return { binPath: resolvedPath, backupPath, timeout };
}
